insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('ea5af73e-53e1-4b2b-8553-e3651929606b', 'N4', 'Aは人＋によって＋V (bị động)', 'A được làm/ phát minh/ chế tạo do/ bởi ai ~', 'によって nêu rõ chủ thể tạo ra sản phẩm/tác phẩm trong câu bị động', 'A + は + [người] + によって + V(thể bị động)', 'Nêu rõ ai là người tạo ra/phát minh ra 1 sự vật', NULL, NULL, NULL, '{}', NULL, 42, 'Aは人＋によって＋V (bị động)', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('6ef1f07f-01cc-4a50-a922-cd898a04c368', 'N4', 'Vる＋の (danh từ hóa bằng の)', 'Danh từ hóa động từ bằng trợ từ の', 'の biến cả mệnh đề động từ thành 1 cụm danh từ', NULL, NULL, NULL, NULL, NULL, '{}', NULL, 42, 'Vる＋の (danh từ hóa bằng の)', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('ef05489a-b775-4fd9-b4ae-13090be73982', 'N4', 'V/Aて (nguyên nhân, lý do)', 'Vì ~ nên ~', 'V/A thể て đứng đầu để nêu nguyên nhân cho vế sau', NULL, NULL, NULL, NULL, NULL, '{}', NULL, 42, 'V/Aて (nguyên nhân, lý do)', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('fd349e0e-797e-43cd-9292-d5e7ec75702f', 'N4', 'V/Aい/Aな/N (thể thông thường)＋ので', 'Vì ~ (mẫu câu dùng để biểu thị quan hệ nguyên nhân – kết quả)', 'ので trung tính, lịch sự hơn から, thường dùng cho lý do khách quan', 'V/Aい/Aな/N (thể thông thường) + ので', 'Nêu nguyên nhân khách quan dẫn đến kết quả 1 cách nhẹ nhàng, lịch sự', NULL, NULL, NULL, '{}', NULL, 42, 'V/Aい/Aな/N (thể thông thường)＋ので', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('f1180dde-2f4c-4337-9ced-0d865ef12863', 'N4', 'Vる／Nの＋途中で', 'Trên đường đi đâu, làm gì ~', '途中で = giữa chừng, trên đường thực hiện việc gì', 'V(thể từ điển)／N + の + 途中で', 'Diễn tả 1 việc xảy ra giữa chừng khi đang làm/đi 1 việc khác', NULL, NULL, NULL, '{}', NULL, 42, 'Vる／Nの＋途中で', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('707f3596-b576-4b7c-b7fd-56eaf8b5b014', 'N4', 'Nghi vấn từ ＋ Aい／Aな／Nか ＋ Động từ', 'Có biết, có nhớ... là (bao nhiêu, ở đâu...) không?', 'Câu hỏi gián tiếp: nghi vấn từ + か lồng vào trong câu', '[nghi vấn từ...] + か + [động từ chính, thường là わかる/知る]', 'Đặt câu hỏi gián tiếp (câu hỏi lồng trong câu)', NULL, NULL, NULL, '{}', NULL, 42, 'Nghi vấn từ ＋ Aい／Aな／Nか ＋ Động từ', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('6ae6544e-1f5c-46f0-9a39-92d0fcc88602', 'N4', '…かどうか…', '... Có hay là không?', 'かどうか lồng câu hỏi Có/Không vào trong câu', '[mệnh đề thể thường] + かどうか', 'Diễn tả sự không chắc chắn về việc có/không xảy ra điều gì', NULL, NULL, NULL, '{}', NULL, 42, '…かどうか…', 'pdf', 'ok')
